CREATE POLICY "Portfolio owner manages portfolio media" ON storage.objects FOR ALL TO authenticated USING (bucket_id = 'portfolio-media' AND lower(coalesce(auth.jwt() ->> 'email', '')) = 'grvnth.design@gmail.com') WITH CHECK (bucket_id = 'portfolio-media' AND lower(coalesce(auth.jwt() ->> 'email', '')) = 'grvnth.design@gmail.com');
CREATE POLICY "Published portfolio media is readable" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'portfolio-media' AND EXISTS (SELECT 1 FROM public.portfolio_projects p JOIN public.portfolio_sections s ON s.id = p.section_id WHERE p.published AND s.visible AND name = ANY(p.media_paths)));